<?php require __DIR__.'/../../layouts/header.php'; ?><div class="toolbar"><div><h1 class="page-title">Alertas MG</h1><p class="subtitle">Se calculan al abrir el panel; no usan cron ni cambian estados automáticamente.</p></div></div><div class="card"><div class="card-body"><div class="table-wrap"><table class="table"><thead><tr><th>Severidad</th><th>Tipo</th><th>Alerta</th><th>Detalle</th><th>Acción</th></tr></thead><tbody><?php foreach($filtradas as $a): ?><tr><td><span class="badge badge-<?=$a['severidad']==='alta'?'danger':($a['severidad']==='media'?'warning':'success')?>"><?=e($a['severidad'])?></span></td><td><?=e($a['tipo'])?></td><td><?=e($a['titulo'])?></td><td><?=e($a['detalle'])?></td><td><a class="btn btn-sm" href="<?=e($a['url'])?>">Ver</a><form method="post" action="/controllers/mg_alertas.php?accion=atender" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="tipo_alerta" value="<?=e($a['tipo'])?>"><input type="hidden" name="id_referencia" value="<?=$a['id']?>"><input name="nota" placeholder="Nota de atención" required><button class="btn btn-sm btn-primary">Atender</button></form></td></tr><?php endforeach;if(!$filtradas): ?><tr><td colspan="5">No hay alertas abiertas.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../../layouts/footer.php'; ?>
